public RefreshFrequency xds()
{
    METTAMRebateCompanyPolicyTmp     metTAMRebateCompanyPolicyTmp;
    METUserSecurityGroupList         metUserSecurityGroupList;
    METUserSecurityRebateCompanyList metUserSecurityRebateCompanyList;

    Unchecked(Uncheck::XDS)
    {
        insert_recordset metTAMRebateCompanyPolicyTmp(RebateCompanyId)
          select RebateCompanyId from metUserSecurityRebateCompanyList
              group by RebateCompanyId
              exists join metUserSecurityGroupList
                  where metUserSecurityGroupList.UserSecurityGroupId == metUserSecurityRebateCompanyList.UserSecurityGroupId
                     && metUserSecurityGroupList.UserId == curUserId();
    }

    return RefreshFrequency::PerSession;
}
